def get_price(ticker, period=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                d = datetime.datetime.fromisoformat(s)
                return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{int(now.timestamp()*1000)}_{random.randint(100000, 999999)}"

    def _log_request(client_id, status, http_status, ticker_in, period_in, instrument_id, cache_hit, latency_ms, error_message=None):
        logs = _load("request_logs.json")
        log_row = {
            "id": _new_id("req"),
            "client_id": client_id,
            "tool_name": "get_price",
            "ticker": ticker_in if isinstance(ticker_in, str) else str(ticker_in),
            "period": period_in,
            "count": None,
            "instrument_id": instrument_id,
            "cache_hit": bool(cache_hit),
            "status": status,
            "http_status": int(http_status),
            "latency_ms": int(max(0, latency_ms)),
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

    def _pick_ambient_client():
        clients = _load("api_clients.json")
        # Prefer any active client that can serve calls; if none, allow anonymous (client_id None)
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if active:
            # Choose the highest limits to reduce accidental rate limiting in shared stores
            active.sort(key=lambda c: (int(c.get("requests_per_day") or 0), int(c.get("requests_per_minute") or 0)), reverse=True)
            return active[0]
        return None

    def _rate_limit_check(client):
        if not client:
            return (True, None)
        if client.get("status") != "active":
            return (False, ("UNAUTHORIZED", f"Client status is {client.get('status')}", client.get("id")))
        client_id = client.get("id")
        rpm = client.get("requests_per_minute")
        rpd = client.get("requests_per_day")
        try:
            rpm = int(rpm)
            rpd = int(rpd)
        except Exception:
            return (False, ("UNAUTHORIZED", "Client rate limits misconfigured", client_id))

        logs = _load("request_logs.json")
        # Count only requests attributed to this client_id
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _dt_parse(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                c_min += 1
            if ts >= day_ago:
                c_day += 1

        if c_min >= rpm or c_day >= rpd:
            return (False, ("RATE_LIMIT", "Rate limit or daily quota exceeded", client_id))
        return (True, client_id)

    # Validate inputs
    if not isinstance(ticker, str):
        latency = int((time.perf_counter() - t0) * 1000)
        client = _pick_ambient_client()
        ok, info = _rate_limit_check(client)
        client_id = client.get("id") if client else None
        if not ok and info[0] == "RATE_LIMIT":
            _log_request(client_id, "rate_limited", 429, ticker, period or "1d", None, False, latency, info[1])
            return _err("RATE_LIMIT", info[1])
        _log_request(client_id, "invalid_argument", 400, str(ticker), period or "1d", None, False, latency, "ticker must be a string")
        return _err("VALIDATION_ERROR", "ticker must be a string")
    ticker_in = ticker
    ticker_norm = ticker.strip()
    if not ticker_norm:
        latency = int((time.perf_counter() - t0) * 1000)
        client = _pick_ambient_client()
        ok, info = _rate_limit_check(client)
        client_id = client.get("id") if client else None
        if not ok and info[0] == "RATE_LIMIT":
            _log_request(client_id, "rate_limited", 429, ticker_in, period or "1d", None, False, latency, info[1])
            return _err("RATE_LIMIT", info[1])
        _log_request(client_id, "invalid_argument", 400, ticker_in, period or "1d", None, False, latency, "ticker cannot be empty")
        return _err("VALIDATION_ERROR", "ticker cannot be empty")

    if period is None:
        period = "1d"
    if not isinstance(period, str):
        latency = int((time.perf_counter() - t0) * 1000)
        client = _pick_ambient_client()
        ok, info = _rate_limit_check(client)
        client_id = client.get("id") if client else None
        if not ok and info[0] == "RATE_LIMIT":
            _log_request(client_id, "rate_limited", 429, ticker_in, str(period), None, False, latency, info[1])
            return _err("RATE_LIMIT", info[1])
        _log_request(client_id, "invalid_argument", 400, ticker_in, None, None, False, latency, "period must be a string")
        return _err("VALIDATION_ERROR", "period must be a string")
    period = period.strip()
    allowed_periods = {"1d", "5d", "1mo", "3mo", "6mo", "1y", "5y", "max"}
    if period not in allowed_periods:
        latency = int((time.perf_counter() - t0) * 1000)
        client = _pick_ambient_client()
        ok, info = _rate_limit_check(client)
        client_id = client.get("id") if client else None
        if not ok and info[0] == "RATE_LIMIT":
            _log_request(client_id, "rate_limited", 429, ticker_in, period, None, False, latency, info[1])
            return _err("RATE_LIMIT", info[1])
        _log_request(client_id, "invalid_argument", 400, ticker_in, period, None, False, latency, "unsupported period")
        return _err("VALIDATION_ERROR", "Unsupported period", allowed=list(sorted(allowed_periods)))

    # Rate limit (ambient)
    client = _pick_ambient_client()
    ok, info = _rate_limit_check(client)
    if not ok:
        code, msg, client_id = info
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(client_id, "rate_limited", 429, ticker_in, period, None, False, latency, msg)
        return _err(code, msg, client_status=(client.get("status") if client else None))
    client_id = info

    instruments = _load("instruments.json")
    snapshots = _load("price_snapshots.json")

    # Resolve instrument by symbol case-insensitive
    inst = None
    for r in instruments:
        if not isinstance(r, dict):
            continue
        sym = r.get("symbol")
        if isinstance(sym, str) and sym.lower() == ticker_norm.lower():
            inst = r
            break

    # Cache policy
    TTL_SECONDS = 60  # configured TTL
    MAX_STALE_SECONDS = 3600  # maximum staleness window for serving stale
    instrument_id = inst.get("id") if inst else None

    def _latest_snapshot_for(inst_id, per, statuses):
        best = None
        best_asof = None
        for s in snapshots:
            if not isinstance(s, dict):
                continue
            if s.get("instrument_id") != inst_id:
                continue
            if s.get("period") != per:
                continue
            if s.get("fetch_status") not in statuses:
                continue
            asof = _dt_parse(s.get("as_of"))
            if not asof:
                continue
            if best is None or asof > best_asof:
                best = s
                best_asof = asof
        return best, best_asof

    # If instrument exists, try cache
    if instrument_id:
        fresh, fresh_asof = _latest_snapshot_for(instrument_id, period, {"fresh"})
        if fresh and fresh_asof and (now - fresh_asof).total_seconds() <= TTL_SECONDS:
            latency = int((time.perf_counter() - t0) * 1000)
            _log_request(client_id, "ok", 200, ticker_in, period, instrument_id, True, latency, None)
            return {
                "instrument": inst,
                "snapshot": fresh,
                "cache": {"hit": True, "fresh": True, "as_of": fresh.get("as_of"), "ttl_seconds": TTL_SECONDS},
            }

    # "Upstream fetch" simulation (offline): succeed only if instrument exists already; otherwise not found.
    # If instrument exists, we can "refresh"; if not, we cannot resolve upstream in offline mode.
    upstream_ok = instrument_id is not None

    if not upstream_ok:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(client_id, "not_found", 404, ticker_in, period, None, False, latency, "ticker could not be resolved by upstream provider")
        return _err("NOT_FOUND", "Ticker not found")

    # Build new snapshot (respect as_of <= now + 5 minutes)
    as_of = now
    if as_of > now + datetime.timedelta(minutes=5):
        as_of = now

    # Enforce uniqueness (instrument_id, period, as_of): if exists, update idempotently to fresh
    existing = None
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("instrument_id") == instrument_id and s.get("period") == period and s.get("as_of") == _iso(as_of):
            existing = s
            break

    # Create a minimal normalized payload; in real service this comes from provider.
    # Keep deterministic but variable across time to appear refreshed.
    seed = int(now.timestamp()) // 60
    h = hashlib.sha256((instrument_id + period + str(seed)).encode("utf-8")).hexdigest()
    base = (int(h[:8], 16) % 50000) / 100.0 + 1.0
    payload = {
        "last": round(base, 4),
        "currency": "USD",
        "period": period,
        "provider": inst.get("provider"),
        "symbol": inst.get("symbol"),
        "as_of": _iso(as_of),
    }

    if existing:
        existing["payload"] = payload
        existing["currency"] = existing.get("currency") or "USD"
        existing["fetch_status"] = "fresh"
        existing["error_message"] = None
        existing["source"] = inst.get("provider") or "other"
        existing["updated_at"] = _iso(now)
        _save("price_snapshots.json", snapshots)
        latency = int((time.perf_counter() - t0) * 1000)
        _log_request(client_id, "ok", 200, ticker_in, period, instrument_id, False, latency, None)
        return {
            "instrument": inst,
            "snapshot": existing,
            "cache": {"hit": False, "fresh": True, "as_of": existing.get("as_of"), "ttl_seconds": TTL_SECONDS},
        }

    new_snapshot = {
        "id": _new_id("ps"),
        "instrument_id": instrument_id,
        "period": period,
        "currency": "USD",
        "as_of": _iso(as_of),
        "payload": payload,
        "fetch_status": "fresh",
        "error_message": None,
        "source": inst.get("provider") or "other",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    snapshots.append(new_snapshot)
    _save("price_snapshots.json", snapshots)

    latency = int((time.perf_counter() - t0) * 1000)
    _log_request(client_id, "ok", 200, ticker_in, period, instrument_id, False, latency, None)
    return {
        "instrument": inst,
        "snapshot": new_snapshot,
        "cache": {"hit": False, "fresh": True, "as_of": new_snapshot.get("as_of"), "ttl_seconds": TTL_SECONDS},
    }

def get_news(ticker, count=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    NEWS_TTL_SECONDS = 15 * 60
    NEWS_MAX_STALE_SECONDS = 24 * 60 * 60

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                d = datetime.datetime.fromisoformat(s)
                return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"fin_{prefix}_01{int(time.time()*1000):013d}{random.randint(0, 999999):06d}"

    def _normalize_ticker(s):
        if not isinstance(s, str):
            return None
        t = s.strip()
        if not t:
            return None
        if len(t) > 64:
            return None
        if not re.fullmatch(r"[A-Za-z0-9._\-]+", t):
            return None
        return t.upper()

    def _append_request_log(*, client_id, tool_name, ticker_in, period, count_in, instrument_id, cache_hit, status, http_status, error_message):
        logs = _load("request_logs.json")
        if isinstance(logs, dict) and "rows" in logs:
            logs = logs["rows"]
        if not isinstance(logs, list):
            logs = []
        latency_ms = max(0, int((time.perf_counter() - t0) * 1000))
        row = {
            "id": _new_id("req"),
            "client_id": client_id,
            "tool_name": tool_name,
            "ticker": ticker_in if isinstance(ticker_in, str) else str(ticker_in),
            "period": period,
            "count": count_in,
            "instrument_id": instrument_id,
            "cache_hit": bool(cache_hit),
            "status": status,
            "http_status": int(http_status),
            "latency_ms": int(latency_ms),
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return row

    def _find_working_client_for_rate_limits():
        clients = _load("api_clients.json")
        if isinstance(clients, dict) and "rows" in clients:
            clients = clients["rows"]
        if not isinstance(clients, list):
            clients = []
        for c in clients:
            try:
                if c.get("status") == "active" and isinstance(c.get("requests_per_minute"), int) and isinstance(c.get("requests_per_day"), int):
                    return c
            except Exception:
                continue
        return None

    def _within_window(log_rows, client_id, since_dt):
        cnt = 0
        for r in log_rows:
            if r.get("client_id") != client_id:
                continue
            cd = _dt_parse(r.get("created_at"))
            if cd is None:
                continue
            if cd >= since_dt:
                cnt += 1
        return cnt

    # Validate inputs
    ticker_norm = _normalize_ticker(ticker)
    if ticker_norm is None:
        _append_request_log(
            client_id=None, tool_name="get_news", ticker_in=ticker if isinstance(ticker, str) else "",
            period=None, count_in=count if count is not None else 5, instrument_id=None,
            cache_hit=False, status="invalid_argument", http_status=400,
            error_message="ticker must be a non-empty string"
        )
        return _err("VALIDATION_ERROR", "Invalid ticker.")

    if count is None:
        count = 5
    if not isinstance(count, int):
        _append_request_log(
            client_id=None, tool_name="get_news", ticker_in=ticker_norm,
            period=None, count_in=count, instrument_id=None,
            cache_hit=False, status="invalid_argument", http_status=400,
            error_message="count must be an integer"
        )
        return _err("VALIDATION_ERROR", "count must be an integer.")
    if count < 1 or count > 100:
        _append_request_log(
            client_id=None, tool_name="get_news", ticker_in=ticker_norm,
            period=None, count_in=count, instrument_id=None,
            cache_hit=False, status="invalid_argument", http_status=400,
            error_message="count must be between 1 and 100"
        )
        return _err("VALIDATION_ERROR", "count must be between 1 and 100.")

    # Ambient auth: select any working active client if present; otherwise anonymous (no rate limiting)
    client = _find_working_client_for_rate_limits()
    client_id = client.get("id") if client else None

    # Rate limiting (only if client_id present)
    logs = _load("request_logs.json")
    if isinstance(logs, dict) and "rows" in logs:
        logs = logs["rows"]
    if not isinstance(logs, list):
        logs = []

    if client_id:
        minute_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)
        rpm_used = _within_window(logs, client_id, minute_ago)
        rpd_used = _within_window(logs, client_id, day_ago)

        if rpm_used >= int(client.get("requests_per_minute", 0)):
            _append_request_log(
                client_id=client_id, tool_name="get_news", ticker_in=ticker_norm,
                period=None, count_in=count, instrument_id=None,
                cache_hit=False, status="rate_limited", http_status=429,
                error_message="Rate limit exceeded (requests_per_minute)"
            )
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if rpd_used >= int(client.get("requests_per_day", 0)):
            _append_request_log(
                client_id=client_id, tool_name="get_news", ticker_in=ticker_norm,
                period=None, count_in=count, instrument_id=None,
                cache_hit=False, status="rate_limited", http_status=429,
                error_message="Rate limit exceeded (requests_per_day)"
            )
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Resolve instrument by symbol (case-insensitive)
    instruments = _load("instruments.json")
    if isinstance(instruments, dict) and "rows" in instruments:
        instruments = instruments["rows"]
    if not isinstance(instruments, list):
        instruments = []

    instrument = None
    for ins in instruments:
        sym = ins.get("symbol")
        if isinstance(sym, str) and sym.strip().upper() == ticker_norm:
            instrument = ins
            break

    if instrument is None:
        _append_request_log(
            client_id=client_id, tool_name="get_news", ticker_in=ticker_norm,
            period=None, count_in=count, instrument_id=None,
            cache_hit=False, status="not_found", http_status=404,
            error_message=f"Ticker '{ticker_norm}' not found."
        )
        return {"data": {"ticker": ticker_norm, "instrument_id": None, "articles": [], "count": 0, "cache": {"hit": False, "fresh": False}}}

    instrument_id = instrument.get("id")

    # Query cache: active articles by published_at desc
    articles = _load("news_articles.json")
    if isinstance(articles, dict) and "rows" in articles:
        articles = articles["rows"]
    if not isinstance(articles, list):
        articles = []

    active_rows = []
    newest_pub = None
    for a in articles:
        if a.get("instrument_id") != instrument_id:
            continue
        if a.get("status") != "active":
            continue
        pd = _dt_parse(a.get("published_at"))
        if pd is None:
            continue
        active_rows.append((pd, a))
        if newest_pub is None or pd > newest_pub:
            newest_pub = pd

    active_rows.sort(key=lambda x: x[0], reverse=True)
    cached = [r for _, r in active_rows[:count]]

    cache_is_fresh = False
    if newest_pub is not None:
        cache_is_fresh = (now - newest_pub).total_seconds() <= NEWS_TTL_SECONDS

    if cached and cache_is_fresh:
        _append_request_log(
            client_id=client_id, tool_name="get_news", ticker_in=ticker_norm,
            period=None, count_in=count, instrument_id=instrument_id,
            cache_hit=True, status="ok", http_status=200, error_message=None
        )
        return {"data": {"ticker": ticker_norm, "instrument_id": instrument_id, "articles": cached, "count": len(cached), "cache": {"hit": True, "fresh": True}}}

    # Offline mode: do not attempt upstream fetch. Serve stale if within max-stale, otherwise upstream_error.
    if cached:
        # Determine staleness window
        if newest_pub is not None and (now - newest_pub).total_seconds() <= NEWS_MAX_STALE_SECONDS:
            _append_request_log(
                client_id=client_id, tool_name="get_news", ticker_in=ticker_norm,
                period=None, count_in=count, instrument_id=instrument_id,
                cache_hit=True, status="ok", http_status=200,
                error_message="Served stale cache due to upstream unavailable in offline mode"
            )
            return {"data": {"ticker": ticker_norm, "instrument_id": instrument_id, "articles": cached, "count": len(cached), "cache": {"hit": True, "fresh": False}}}

    _append_request_log(
        client_id=client_id, tool_name="get_news", ticker_in=ticker_norm,
        period=None, count_in=count, instrument_id=instrument_id,
        cache_hit=False, status="upstream_error", http_status=502,
        error_message="Upstream news provider unavailable in offline mode"
    )
    return _err("CONFLICT", "Upstream error.", detail="Upstream news provider unavailable in offline mode")

def get_me(api_key, **_extra):
    import json, os, datetime, time, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                d = datetime.datetime.fromisoformat(s)
                return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{int(now.timestamp()*1000)}_{random.randint(100000, 999999)}"

    def _log_request(client_id, status, http_status, error_message=None, ticker="-", period=None, count=None, instrument_id=None, cache_hit=False):
        logs = _load("request_logs.json")
        log_row = {
            "id": _new_id("req"),
            "client_id": client_id,
            "tool_name": "get_price" if False else "get_news",  # enum only supports get_price/get_news; use get_news as generic identity call log
            "ticker": ticker,
            "period": period,
            "count": count,
            "instrument_id": instrument_id,
            "cache_hit": bool(cache_hit),
            "status": status,
            "http_status": int(http_status),
            "latency_ms": int(max(0, (time.perf_counter() - t0) * 1000)),
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "invalid_argument", 400, "api_key must be a non-empty string", ticker="__get_me__")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_key = api_key.strip()
    clients = _load("api_clients.json")

    # Authenticate by matching either client id or stored client-visible value.
    # Store only has api_key_hash; accept api_key if it equals api_key_hash OR equals client id.
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if not client:
        _log_request(None, "invalid_argument", 401, "invalid api key", ticker="__get_me__")
        return _err("UNAUTHORIZED", "Invalid API key")

    if client.get("status") != "active":
        _log_request(client.get("id"), "invalid_argument", 403, f"client is {client.get('status')}", ticker="__get_me__")
        return _err("UNAUTHORIZED", "Client not permitted", client_status=client.get("status"))

    # Usage computation
    logs = _load("request_logs.json")
    minute_ago = now - datetime.timedelta(minutes=1)
    day_ago = now - datetime.timedelta(days=1)
    used_min = 0
    used_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client.get("id"):
            continue
        ts = _dt_parse(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_ago:
            used_min += 1
        if ts >= day_ago:
            used_day += 1

    rpm = int(client.get("requests_per_minute") or 0)
    rpd = int(client.get("requests_per_day") or 0)

    _log_request(client.get("id"), "ok", 200, None, ticker="__get_me__", cache_hit=True)

    return {
        "client": {
            "id": client.get("id"),
            "name": client.get("name"),
            "status": client.get("status"),
            "created_at": client.get("created_at"),
            "updated_at": client.get("updated_at"),
        },
        "entitlements": {
            "tools": ["get_price", "get_news", "list_instruments"],
            "scopes": ["read:prices", "read:news", "read:instruments"],
        },
        "rate_limit": {
            "requests_per_minute": rpm,
            "requests_per_day": rpd,
            "used_last_minute": used_min,
            "used_last_day": used_day,
            "remaining_this_minute": max(0, rpm - used_min),
            "remaining_today": max(0, rpd - used_day),
        },
    }

def list_instruments(api_key, symbol=None, asset_type=None, exchange=None, provider=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, (int, float)):
            return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                d = datetime.datetime.fromisoformat(s)
                return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{int(now.timestamp()*1000)}_{random.randint(100000, 999999)}"

    def _log_request(client_id, status_s, http_status, error_message=None):
        logs = _load("request_logs.json")
        # enum only supports get_price/get_news; log as get_news with special ticker
        log_row = {
            "id": _new_id("req"),
            "client_id": client_id,
            "tool_name": "get_news",
            "ticker": "__list_instruments__",
            "period": None,
            "count": None,
            "instrument_id": None,
            "cache_hit": True,
            "status": status_s,
            "http_status": int(http_status),
            "latency_ms": int(max(0, (time.perf_counter() - t0) * 1000)),
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

    # Validate api_key
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "invalid_argument", 400, "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_key = api_key.strip()
    clients = _load("api_clients.json")
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            client = c
            break
    if not client:
        _log_request(None, "invalid_argument", 401, "invalid api key")
        return _err("UNAUTHORIZED", "Invalid API key")
    if client.get("status") != "active":
        _log_request(client.get("id"), "invalid_argument", 403, f"client is {client.get('status')}")
        return _err("UNAUTHORIZED", "Client not permitted", client_status=client.get("status"))

    # Validate filters
    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        _log_request(client.get("id"), "invalid_argument", 400, "symbol must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided")
    if asset_type is not None:
        if not isinstance(asset_type, str):
            _log_request(client.get("id"), "invalid_argument", 400, "asset_type must be a string")
            return _err("VALIDATION_ERROR", "asset_type must be a string")
        allowed_asset = {"stock", "crypto", "forex", "etf", "index"}
        if asset_type not in allowed_asset:
            _log_request(client.get("id"), "invalid_argument", 400, "unsupported asset_type")
            return _err("VALIDATION_ERROR", "Unsupported asset_type", allowed=list(sorted(allowed_asset)))
    if status is not None:
        if not isinstance(status, str):
            _log_request(client.get("id"), "invalid_argument", 400, "status must be a string")
            return _err("VALIDATION_ERROR", "status must be a string")
        allowed_status = {"active", "inactive", "delisted"}
        if status not in allowed_status:
            _log_request(client.get("id"), "invalid_argument", 400, "unsupported status")
            return _err("VALIDATION_ERROR", "Unsupported status", allowed=list(sorted(allowed_status)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log_request(client.get("id"), "invalid_argument", 400, "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log_request(client.get("id"), "invalid_argument", 400, "limit must be between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if exchange is not None and not isinstance(exchange, str):
        _log_request(client.get("id"), "invalid_argument", 400, "exchange must be a string")
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if provider is not None and not isinstance(provider, str):
        _log_request(client.get("id"), "invalid_argument", 400, "provider must be a string")
        return _err("VALIDATION_ERROR", "provider must be a string")

    instruments = _load("instruments.json")

    # Filter
    out = []
    sym_filter = symbol.strip().lower() if isinstance(symbol, str) else None
    exch_filter = exchange.strip() if isinstance(exchange, str) else None
    prov_filter = provider.strip() if isinstance(provider, str) else None

    for r in instruments:
        if not isinstance(r, dict):
            continue
        if sym_filter is not None:
            sym = r.get("symbol")
            if not (isinstance(sym, str) and sym.lower() == sym_filter):
                continue
        if asset_type is not None and r.get("asset_type") != asset_type:
            continue
        if exch_filter is not None:
            if (r.get("exchange") or "") != exch_filter:
                continue
        if prov_filter is not None and r.get("provider") != prov_filter:
            continue
        if status is not None and r.get("status") != status:
            continue
        out.append(r)

    # Sort by updated_at desc
    def _updated_key(r):
        d = _dt_parse(r.get("updated_at")) or _dt_parse(r.get("created_at"))
        return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    out.sort(key=_updated_key, reverse=True)

    # Cursor: opaque integer offset
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log_request(client.get("id"), "invalid_argument", 400, "cursor must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            if not cursor.startswith("off:"):
                raise ValueError("bad cursor")
            offset = int(cursor.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log_request(client.get("id"), "invalid_argument", 400, "invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    total = len(out)
    page = out[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"off:{next_offset}" if has_more else None

    _log_request(client.get("id"), "ok", 200, None)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

def get_instrument(api_key, instrument_id, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_request(client_id, tool_name, ticker, period, count, instrument_id_resolved, cache_hit, status, http_status, error_message):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rlog"),
            "client_id": client_id,
            "tool_name": tool_name,
            "ticker": ticker if ticker is not None else "",
            "period": period,
            "count": count,
            "instrument_id": instrument_id_resolved,
            "cache_hit": bool(cache_hit),
            "status": status,
            "http_status": int(http_status),
            "latency_ms": max(0, int((time.time() - _t0) * 1000)),
            "error_message": error_message,
            "created_at": _iso(_now),
            "updated_at": _iso(_now),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return row

    def _auth_client(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        api_key_value = api_key_value.strip()
        clients = _load("api_clients.json")
        for c in clients:
            if c.get("id") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        for c in clients:
            if c.get("api_key_hash") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        return None

    def _rate_limit_ok(client_id):
        if client_id is None:
            return True, None
        clients = _load("api_clients.json")
        client = next((c for c in clients if c.get("id") == client_id), None)
        if not client or client.get("status") != "active":
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        rpm = client.get("requests_per_minute")
        rpd = client.get("requests_per_day")
        if not isinstance(rpm, int) or not isinstance(rpd, int):
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        now = _now
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        logs = _load("request_logs.json")
        used_min = 0
        used_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_rfc3339(r.get("created_at"))
            if not dt:
                continue
            if dt >= minute_ago:
                used_min += 1
            if dt >= day_ago:
                used_day += 1
        if used_min >= rpm or used_day >= rpd:
            return False, ("RATE_LIMIT", "Rate limit or daily quota exceeded.")
        return True, None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "get_price", ticker="", period=None, count=None, instrument_id_resolved=None, cache_hit=False,
                     status="invalid_argument", http_status=400, error_message="api_key is required.")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(instrument_id, str) or not instrument_id.strip():
        _log_request(None, "get_price", ticker="", period=None, count=None, instrument_id_resolved=None, cache_hit=False,
                     status="invalid_argument", http_status=400, error_message="instrument_id is required.")
        return _err("VALIDATION_ERROR", "instrument_id must be a non-empty string.")

    client = _auth_client(api_key)
    if not client:
        _log_request(None, "get_price", ticker="", period=None, count=None, instrument_id_resolved=None, cache_hit=False,
                     status="invalid_argument", http_status=401, error_message="Unauthorized.")
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")

    ok, why = _rate_limit_ok(client.get("id"))
    if not ok:
        _log_request(client.get("id"), "get_price", ticker="", period=None, count=None, instrument_id_resolved=None, cache_hit=False,
                     status="rate_limited", http_status=429, error_message=why[1])
        return _err("RATE_LIMIT", why[1])

    instruments = _load("instruments.json")
    inst = next((i for i in instruments if i.get("id") == instrument_id.strip()), None)

    if not inst:
        _log_request(client.get("id"), "get_price", ticker="", period=None, count=None, instrument_id_resolved=None, cache_hit=False,
                     status="not_found", http_status=404, error_message="Instrument not found.")
        return _err("NOT_FOUND", "Instrument not found.")

    _log_request(client.get("id"), "get_price", ticker=inst.get("symbol") or "", period=None, count=None,
                 instrument_id_resolved=inst.get("id"), cache_hit=True, status="ok", http_status=200, error_message=None)

    return {"instrument": inst}

def create_instrument(api_key, symbol, asset_type, exchange=None, name=None, provider=None, provider_instrument_id=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _auth_client(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        api_key_value = api_key_value.strip()
        clients = _load("api_clients.json")
        for c in clients:
            if c.get("id") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        for c in clients:
            if c.get("api_key_hash") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        return None

    def _rate_limit_ok(client_id):
        if client_id is None:
            return True, None
        clients = _load("api_clients.json")
        client = next((c for c in clients if c.get("id") == client_id), None)
        if not client or client.get("status") != "active":
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        rpm = client.get("requests_per_minute")
        rpd = client.get("requests_per_day")
        if not isinstance(rpm, int) or not isinstance(rpd, int):
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        now = _now
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        logs = _load("request_logs.json")
        used_min = 0
        used_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00")) if isinstance(ca, str) else None
            except Exception:
                dt = None
            if not dt:
                continue
            if dt >= minute_ago:
                used_min += 1
            if dt >= day_ago:
                used_day += 1
        if used_min >= rpm or used_day >= rpd:
            return False, ("RATE_LIMIT", "Rate limit or daily quota exceeded.")
        return True, None

    def _log_minimal(status_code, message):
        # This tool is not part of request_logs.tool_name enum; do not write invalid rows.
        return

    # Validate auth
    client = _auth_client(api_key)
    if not client:
        _log_minimal(401, "Unauthorized")
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")
    ok, why = _rate_limit_ok(client.get("id"))
    if not ok:
        _log_minimal(429, why[1])
        return _err("RATE_LIMIT", why[1])

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string.")
    sym_norm = symbol.strip().upper()
    if len(sym_norm) < 1 or len(sym_norm) > 32:
        return _err("VALIDATION_ERROR", "symbol length must be between 1 and 32.")
    if not isinstance(asset_type, str):
        return _err("VALIDATION_ERROR", "asset_type must be a string.")
    # Note: tool enum includes forex/etf/index but schema allows only stock/crypto.
    if asset_type not in ("stock", "crypto"):
        return _err("VALIDATION_ERROR", "asset_type must be one of: stock, crypto.")
    if exchange is not None and (not isinstance(exchange, str) or not exchange.strip()):
        return _err("VALIDATION_ERROR", "exchange must be a non-empty string when provided.")
    exch_norm = exchange.strip().upper() if isinstance(exchange, str) else None
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
    if provider is None:
        provider_val = "other"
    else:
        if not isinstance(provider, str) or not provider.strip():
            return _err("VALIDATION_ERROR", "provider must be a non-empty string when provided.")
        provider_val = provider.strip()
    if provider_val not in ("yahoo_finance", "coingecko", "other"):
        return _err("VALIDATION_ERROR", "provider must be one of: yahoo_finance, coingecko, other.")
    if provider_instrument_id is not None and (not isinstance(provider_instrument_id, str) or not provider_instrument_id.strip()):
        return _err("VALIDATION_ERROR", "provider_instrument_id must be a non-empty string when provided.")
    if status is None:
        status_val = "active"
    else:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        if status not in ("active", "inactive", "delisted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, delisted.")
        status_val = status

    instruments = _load("instruments.json")

    # Uniqueness: (symbol, exchange, asset_type) case-insensitive normalization
    def _key(row):
        return (
            (row.get("symbol") or "").strip().upper(),
            (row.get("exchange") or "").strip().upper() if row.get("exchange") is not None else None,
            (row.get("asset_type") or "").strip()
        )

    new_key = (sym_norm, exch_norm, asset_type)
    for row in instruments:
        if _key(row) == new_key:
            return _err("CONFLICT", "Instrument with the same (symbol, exchange, asset_type) already exists.", instrument_id=row.get("id"))

    inst = {
        "id": _new_id("inst"),
        "symbol": sym_norm,
        "asset_type": asset_type,
        "exchange": exch_norm,
        "name": name.strip() if isinstance(name, str) else None,
        "provider": provider_val,
        "provider_instrument_id": provider_instrument_id.strip() if isinstance(provider_instrument_id, str) else None,
        "status": status_val,
        "created_at": _iso(_now),
        "updated_at": _iso(_now),
    }
    instruments.append(inst)
    _save("instruments.json", instruments)

    return {"instrument": inst}

def update_instrument(api_key, instrument_id, symbol=None, asset_type=None, exchange=None, name=None, provider=None, provider_instrument_id=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now.isoformat().replace("+00:00", "Z")

    def _auth_client(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        api_key_value = api_key_value.strip()
        clients = _load("api_clients.json")
        for c in clients:
            if c.get("id") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        for c in clients:
            if c.get("api_key_hash") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        return None

    def _rate_limit_ok(client_id):
        if client_id is None:
            return True, None
        clients = _load("api_clients.json")
        client = next((c for c in clients if c.get("id") == client_id), None)
        if not client or client.get("status") != "active":
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        rpm = client.get("requests_per_minute")
        rpd = client.get("requests_per_day")
        if not isinstance(rpm, int) or not isinstance(rpd, int):
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        now = _now
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        logs = _load("request_logs.json")
        used_min = 0
        used_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            ca = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ca.replace("Z", "+00:00")) if isinstance(ca, str) else None
            except Exception:
                dt = None
            if not dt:
                continue
            if dt >= minute_ago:
                used_min += 1
            if dt >= day_ago:
                used_day += 1
        if used_min >= rpm or used_day >= rpd:
            return False, ("RATE_LIMIT", "Rate limit or daily quota exceeded.")
        return True, None

    # Auth
    client = _auth_client(api_key)
    if not client:
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")
    ok, why = _rate_limit_ok(client.get("id"))
    if not ok:
        return _err("RATE_LIMIT", why[1])

    if not isinstance(instrument_id, str) or not instrument_id.strip():
        return _err("VALIDATION_ERROR", "instrument_id must be a non-empty string.")
    instrument_id = instrument_id.strip()

    instruments = _load("instruments.json")
    idx = next((i for i, r in enumerate(instruments) if r.get("id") == instrument_id), None)
    if idx is None:
        return _err("NOT_FOUND", "Instrument not found.")
    inst = instruments[idx]

    # Validate fields
    if symbol is not None:
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided.")
        sym_norm = symbol.strip().upper()
        if len(sym_norm) < 1 or len(sym_norm) > 32:
            return _err("VALIDATION_ERROR", "symbol length must be between 1 and 32.")
    else:
        sym_norm = (inst.get("symbol") or "").strip().upper()

    if asset_type is not None:
        if not isinstance(asset_type, str):
            return _err("VALIDATION_ERROR", "asset_type must be a string when provided.")
        if asset_type not in ("stock", "crypto"):
            return _err("VALIDATION_ERROR", "asset_type must be one of: stock, crypto.")
        at_val = asset_type
    else:
        at_val = inst.get("asset_type")

    if exchange is not None:
        if not isinstance(exchange, str) or not exchange.strip():
            return _err("VALIDATION_ERROR", "exchange must be a non-empty string when provided.")
        exch_norm = exchange.strip().upper()
    else:
        exch_norm = inst.get("exchange")
        exch_norm = exch_norm.strip().upper() if isinstance(exch_norm, str) else None

    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
    if provider is not None:
        if not isinstance(provider, str) or not provider.strip():
            return _err("VALIDATION_ERROR", "provider must be a non-empty string when provided.")
        prov_val = provider.strip()
        if prov_val not in ("yahoo_finance", "coingecko", "other"):
            return _err("VALIDATION_ERROR", "provider must be one of: yahoo_finance, coingecko, other.")
    else:
        prov_val = inst.get("provider")

    if provider_instrument_id is not None and (not isinstance(provider_instrument_id, str) or not provider_instrument_id.strip()):
        return _err("VALIDATION_ERROR", "provider_instrument_id must be a non-empty string when provided.")

    # Lifecycle transition for status
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "inactive", "delisted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, delisted.")
        cur = inst.get("status")
        transitions = {"active": ["inactive", "delisted"], "inactive": ["active", "delisted"], "delisted": []}
        if status != cur:
            if cur not in transitions or status not in transitions[cur]:
                return _err("CONFLICT", "Invalid lifecycle transition.", from_status=cur, to_status=status)
            inst["status"] = status

    # Uniqueness if key fields change
    def _key(row):
        return (
            (row.get("symbol") or "").strip().upper(),
            (row.get("exchange") or "").strip().upper() if row.get("exchange") is not None else None,
            (row.get("asset_type") or "").strip()
        )

    new_key = (sym_norm, exch_norm, at_val)
    old_key = _key(inst)
    if new_key != old_key:
        for row in instruments:
            if row.get("id") == instrument_id:
                continue
            if _key(row) == new_key:
                return _err("CONFLICT", "Instrument with the same (symbol, exchange, asset_type) already exists.", instrument_id=row.get("id"))

    # Apply updates
    if symbol is not None:
        inst["symbol"] = sym_norm
    if asset_type is not None:
        inst["asset_type"] = at_val
    if exchange is not None:
        inst["exchange"] = exch_norm
    if name is not None:
        inst["name"] = name.strip()
    if provider is not None:
        inst["provider"] = prov_val
    if provider_instrument_id is not None:
        inst["provider_instrument_id"] = provider_instrument_id.strip()

    inst["updated_at"] = _iso(_now)
    instruments[idx] = inst
    _save("instruments.json", instruments)

    return {"instrument": inst}

def list_request_logs(api_key, tool_name=None, ticker=None, status=None, cache_hit=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0050000" if __import__("os").path.isdir("./environment_mix/0050000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _auth_client(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        api_key_value = api_key_value.strip()
        clients = _load("api_clients.json")
        for c in clients:
            if c.get("id") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        for c in clients:
            if c.get("api_key_hash") == api_key_value:
                if c.get("status") == "active":
                    return c
                return None
        return None

    def _rate_limit_ok(client_id):
        if client_id is None:
            return True, None
        clients = _load("api_clients.json")
        client = next((c for c in clients if c.get("id") == client_id), None)
        if not client or client.get("status") != "active":
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        rpm = client.get("requests_per_minute")
        rpd = client.get("requests_per_day")
        if not isinstance(rpm, int) or not isinstance(rpd, int):
            return False, ("UNAUTHORIZED", "Client is not authorized.")
        now = _now
        minute_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        logs = _load("request_logs.json")
        used_min = 0
        used_day = 0
        for r in logs:
            if r.get("client_id") != client_id:
                continue
            dt = _parse_rfc3339(r.get("created_at"))
            if not dt:
                continue
            if dt >= minute_ago:
                used_min += 1
            if dt >= day_ago:
                used_day += 1
        if used_min >= rpm or used_day >= rpd:
            return False, ("RATE_LIMIT", "Rate limit or daily quota exceeded.")
        return True, None

    def _log_request(client_id, status_val, http_status, error_message):
        logs = _load("request_logs.json")
        row = {
            "id": _new_id("rlog"),
            "client_id": client_id,
            "tool_name": "get_price",  # enum does not include list_request_logs; pick a valid tool for internal logging
            "ticker": "",
            "period": None,
            "count": None,
            "instrument_id": None,
            "cache_hit": False,
            "status": status_val,
            "http_status": int(http_status),
            "latency_ms": max(0, int((time.time() - _t0) * 1000)),
            "error_message": error_message,
            "created_at": _iso(_now),
            "updated_at": _iso(_now),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Auth
    client = _auth_client(api_key)
    if not client:
        _log_request(None, "invalid_argument", 401, "Unauthorized.")
        return _err("UNAUTHORIZED", "Invalid or inactive API key.")

    ok, why = _rate_limit_ok(client.get("id"))
    if not ok:
        _log_request(client.get("id"), "rate_limited", 429, why[1])
        return _err("RATE_LIMIT", why[1])

    # Validate filters
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in ("get_price", "get_news"):
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid tool_name.")
            return _err("VALIDATION_ERROR", "tool_name must be one of: get_price, get_news.")
    if ticker is not None and (not isinstance(ticker, str) or not ticker.strip()):
        _log_request(client.get("id"), "invalid_argument", 400, "Invalid ticker.")
        return _err("VALIDATION_ERROR", "ticker must be a non-empty string when provided.")
    if status is not None:
        if not isinstance(status, str) or status not in ("ok", "not_found", "rate_limited", "upstream_error", "invalid_argument"):
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid status.")
            return _err("VALIDATION_ERROR", "status must be one of: ok, not_found, rate_limited, upstream_error, invalid_argument.")
    if cache_hit is not None and not isinstance(cache_hit, bool):
        _log_request(client.get("id"), "invalid_argument", 400, "Invalid cache_hit.")
        return _err("VALIDATION_ERROR", "cache_hit must be a boolean when provided.")

    if limit is None:
        limit_val = 50
    else:
        if not isinstance(limit, int):
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid limit.")
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid limit range.")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
        limit_val = limit

    from_dt = None
    to_dt = None
    if from_created_at is not None:
        from_dt = _parse_rfc3339(from_created_at)
        if not from_dt:
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid from_created_at.")
            return _err("VALIDATION_ERROR", "from_created_at must be an RFC 3339 timestamp.")
    if to_created_at is not None:
        to_dt = _parse_rfc3339(to_created_at)
        if not to_dt:
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid to_created_at.")
            return _err("VALIDATION_ERROR", "to_created_at must be an RFC 3339 timestamp.")
    if from_dt and to_dt and from_dt > to_dt:
        _log_request(client.get("id"), "invalid_argument", 400, "Invalid time range.")
        return _err("VALIDATION_ERROR", "from_created_at must be <= to_created_at.")

    # Cursor decoding: base64 JSON {"before": "<rfc3339>", "before_id": "<id>"}
    before_dt = None
    before_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_request(client.get("id"), "invalid_argument", 400, "Invalid cursor.")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            before_dt = _parse_rfc3339(obj.get("before"))
            before_id = obj.get("before_id")
            if before_dt is None or not isinstance(before_id, str) or not before_id:
                raise ValueError("bad cursor")
        except Exception:
            _log_request(client.get("id"), "invalid_argument", 400, "Malformed cursor.")
            return _err("VALIDATION_ERROR", "cursor is invalid or malformed.")

    logs = _load("request_logs.json")
    cid = client.get("id")
    rows = [r for r in logs if r.get("client_id") == cid]

    # Apply filters
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if ticker is not None:
        tnorm = ticker.strip().upper()
        rows = [r for r in rows if isinstance(r.get("ticker"), str) and r.get("ticker").strip().upper() == tnorm]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if cache_hit is not None:
        rows = [r for r in rows if bool(r.get("cache_hit")) == cache_hit]
    if from_dt is not None:
        rows = [r for r in rows if (lambda d: d is not None and d >= from_dt)(_parse_rfc3339(r.get("created_at")))]
    if to_dt is not None:
        rows = [r for r in rows if (lambda d: d is not None and d <= to_dt)(_parse_rfc3339(r.get("created_at")))]

    # Order newest first (created_at desc, then id desc)
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor (before)
    if before_dt is not None and before_id is not None:
        filtered = []
        for r in rows:
            dt = _parse_rfc3339(r.get("created_at"))
            if dt is None:
                continue
            rid = str(r.get("id") or "")
            if dt < before_dt or (dt == before_dt and rid < before_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit_val]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_rfc3339(last.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        payload = {"before": _iso(last_dt), "before_id": str(last.get("id") or "")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log_request(client.get("id"), "ok", 200, None)

    return {
        "request_logs": page,
        "meta": {
            "total": total,
            "limit": limit_val,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
